CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.audit_events` (event_id STRING NOT NULL,case_id STRING,actor_type STRING,actor_id STRING,action STRING,entity_type STRING,entity_id STRING,previous_value_hash STRING,new_value_hash STRING,event_timestamp TIMESTAMP NOT NULL,service_version STRING) PARTITION BY DATE(event_timestamp) CLUSTER BY action,case_id;
CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.review_tasks` (task_id STRING NOT NULL,case_id STRING,document_id STRING,task_type STRING,status STRING,assigned_to STRING,created_at TIMESTAMP,completed_at TIMESTAMP) PARTITION BY DATE(created_at) CLUSTER BY status,assigned_to;
CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.processing_metrics` (event_id STRING,document_id STRING,event_type STRING,duration_ms INT64,status STRING,error_code STRING,service_version STRING,event_timestamp TIMESTAMP) PARTITION BY DATE(event_timestamp) CLUSTER BY status,event_type;
